def solve():
    memo_v = {}
    memo_w = {}

    def get_v(s):
        s = tuple(sorted([x for x in s if x > 0]))
        if not s:
            return 0
        if s in memo_v:
            return memo_v[s]

        # Check if any move is possible
        possible_moves = []
        for i, m in enumerate(s):
            for j in range(1, m):
                possible_moves.append((i, j))

        if not possible_moves:
            res = sum(s)
            memo_v[s] = res
            return res

        res = -float('inf')
        for i, j in possible_moves:
            m = s[i]
            new_s = list(s)
            new_s.pop(i)
            new_s.append(j-1)
            new_s.append(m-j-1)
            res = max(res, get_w(tuple(new_s)))

        memo_v[s] = res
        return res

    def get_w(s):
        s = tuple(sorted([x for x in s if x > 0]))
        if not s:
            return 0
        if s in memo_w:
            return memo_w[s]

        possible_moves = []
        for i, m in enumerate(s):
            for j in range(1, m):
                possible_moves.append((i, j))

        if not possible_moves:
            res = sum(s)
            memo_w[s] = res
            return res

        res = float('inf')
        for i, j in possible_moves:
            m = s[i]
            new_s = list(s)
            new_s.pop(i)
            new_s.append(j-1)
            new_s.append(m-j-1)
            res = min(res, get_v(tuple(new_s)))

        memo_w[s] = res
        return res

    for n in range(1, 15):
        print(f"f({n}) = {get_v((n,))}")

